import{_ as p,W as l,s as o,u as d,ah as c,I as i,w as s,Z as n,A as t}from"./chunks/framework.DYeiaKBS.js";import"./chunks/theme.DJBbXXYU.js";const w=JSON.parse('{"title":"使用 Linux 命令行与其他用户进行通信 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 命令行与其他用户进行通信 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 命令行与其他用户进行通信 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 命令行与其他用户进行通信 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200306 Communicating with other users on the Linux command line","title":"使用 Linux 命令行与其他用户进行通信","tag":"202003"},"relativePath":"202003/20200306 Communicating with other users on the Linux command line.md","filePath":"[post].md"}'),r={name:"202003/20200306 Communicating with other users on the Linux command line.md"};function h(u,a,g,m,b,k){const e=l("Link");return d(),o("div",null,[a[15]||(a[15]=c(`<h1 id="使用-linux-命令行与其他用户进行通信" tabindex="-1">使用 Linux 命令行与其他用户进行通信 <a class="header-anchor" href="#使用-linux-命令行与其他用户进行通信" aria-label="Permalink to 使用 Linux 命令行与其他用户进行通信">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202003/22/171055z3q772v2zq320zx3.jpg" alt=""></p><p>使用 Linux 命令行向其他用户发送消息或许非常容易，这里有一些相关的命令你可以考虑使用。在这篇文章中，我们会考察 4 个这样的命令，看看它们是怎么工作的。</p><h3 id="wall" tabindex="-1">wall <a class="header-anchor" href="#wall" aria-label="Permalink to wall">​</a></h3><p><code>wall</code>（“Write ALL” 的简称）命令允许你向所有系统中已登录的用户发送一条信息。这里我们假设用户都使用命令行在同一台服务器上工作。虽然 <code>wall</code> 命令最常被系统管理员用于向用户发布公告和传递信息（比如说，服务器即将因维护而关闭)，但它可以被任何用户使用。</p><p>系统管理员可能会用类似下面的方式发送信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wall The system will be going down in 15 minutes to address a serious problem</span></span></code></pre></div><p>而所有登录的用户都将看到类似这样的信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Broadcast message from admin@dragonfly (pts/0) (Thu Mar  5 08:56:42 2020):</span></span>
<span class="line"><span>The system is going down in 15 minutes to address a serious problem</span></span></code></pre></div><p>如果希望在消息中使用单引号，你可以像这样将信息用双引号括起来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wall &quot;Don&#39;t forget to save your work before logging off&quot;</span></span></code></pre></div><p>最外层的双引号不会出现在发出的消息中，但是如果没有它们，<code>wall</code> 会停下并等待输入一个配对的单引号。</p><h3 id="mesg" tabindex="-1">mesg <a class="header-anchor" href="#mesg" aria-label="Permalink to mesg">​</a></h3><p>如果出于某种理由你不想接收来自另一个用户的消息，你可以使用 <code>mesg</code> 命令来屏蔽这些消息。这个命令可以接受一个 <code>n</code> 作为参数来拒绝某用户的消息，或者接收一个 <code>y</code> 作为参数来接收用户发来的消息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mesg n doug</span></span>
<span class="line"><span>$ mesg y doug</span></span></code></pre></div><p>被屏蔽的用户不会被告知这一事实。你也可以像这样使用 <code>mesg</code> 来屏蔽或者接收所有消息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ mesg y</span></span>
<span class="line"><span>$ mesg n</span></span></code></pre></div><h3 id="write" tabindex="-1">write <a class="header-anchor" href="#write" aria-label="Permalink to write">​</a></h3><p>另一个在不使用电子邮件的情况下发送文本的命令是 <code>write</code>，这个命令可以用来和一个特定的用户通信。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ write nemo</span></span>
<span class="line"><span>Are you still at your desk?</span></span>
<span class="line"><span>I need to talk with you right away.</span></span>
<span class="line"><span>^C</span></span></code></pre></div><p>输入你的信息后用 <code>ctrl-c</code> 退出，这样就完成了通信。这个命令允许你发送文本，但并不会建立一个双向的通话。它只是将文本发送过去而已。如果目标用户在多个终端上登录，你可以指定你想将消息发送到哪一个终端，否则系统会选择空闲时间最短的那个终端。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ write nemo#1</span></span></code></pre></div><p>如果你试图向一个将消息屏蔽了的用户发送信息，你应该会看到这样的输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ write nemo</span></span>
<span class="line"><span>write: nemo has messages disabled</span></span></code></pre></div><h3 id="talk-ytalk" tabindex="-1">talk/ytalk <a class="header-anchor" href="#talk-ytalk" aria-label="Permalink to talk/ytalk">​</a></h3><p><code>talk</code> 和 <code>ytalk</code> 命令让你可以和一个或多个用户进行交互式的聊天。它们会展示一个有上下两个子窗口的界面，每个用户向显示在他们屏幕上方的窗口内输入内容，并在下方的窗口看到回复信息。要回复一个<code>talk</code> 请求，接收方可以输入 <code>talk</code>，在后面加上请求方的用户名。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Message from Talk_Daemon@dragonfly at 10:10 ...</span></span>
<span class="line"><span>talk: connection requested by dory@127.0.0.1.</span></span>
<span class="line"><span>talk: respond with:  talk dory@127.0.0.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ talk dory</span></span></code></pre></div><p>如果使用的是 <code>ytalk</code>，那么窗口中可以包含多于两个参与者。正如下面的例子所展示的（这是上面 <code>talk dory</code> 命令的结果），<code>talk</code> 通常指向 <code>ytalk</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>----------------------------= YTalk version 3.3.0 =--------------------------</span></span>
<span class="line"><span>Is the report ready?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-------------------------------= nemo@dragonfly =----------------------------</span></span>
<span class="line"><span>Just finished it</span></span></code></pre></div><p>如上所述，在通话的另一侧，<code>talk</code>会话界面的窗口是相反的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>----------------------------= YTalk version 3.3.0 =--------------------------</span></span>
<span class="line"><span>Just finished it</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-------------------------------= dory@dragonfly =----------------------------</span></span>
<span class="line"><span>Is the report ready?</span></span></code></pre></div><p>同样的，使用 <code>ctrl-c</code> 来退出。</p><p>如果要和非本机的用户通讯，你需要加上 <code>-h</code> 选项和目标主机名或IP地址，就像这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ talk -h 192.168.0.11 nemo</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>Linux 上有若干基本的命令可以用来向其他登录的用户发送消息。如果你需要向所有用户快速发送信息或是需要便捷的电话替代品，又或是希望能简单地开始一个多用户快速通讯会话，这些命令会十分实用。</p><p>一些命令如 <code>wall</code> 允许广播消息但却不是交互式的。另外的一些命令如 <code>talk</code> 允许多用户进行长时间通讯，当你只需要非常快速地交换一些信息，它们可以你你避免建立一个电话会议。</p><hr>`,38)),i("p",null,[a[1]||(a[1]=s("via: ")),n(e,{href:"https://www.networkworld.com/article/3530343/communicating-with-other-users-on-the-linux-command-line.html"},{default:t(()=>a[0]||(a[0]=[s("https://www.networkworld.com/article/3530343/communicating-with-other-users-on-the-linux-command-line.html")])),_:1})]),i("p",null,[a[6]||(a[6]=s("作者：")),n(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>a[2]||(a[2]=[s("Sandra Henry-Stocker")])),_:1}),a[7]||(a[7]=s(" 选题：")),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>a[3]||(a[3]=[s("lujun9972")])),_:1}),a[8]||(a[8]=s(" 译者：")),n(e,{href:"https://github.com/linusboyle"},{default:t(()=>a[4]||(a[4]=[s("linusboyle")])),_:1}),a[9]||(a[9]=s(" 校对：")),n(e,{href:"https://github.com/wxy"},{default:t(()=>a[5]||(a[5]=[s("wxy")])),_:1})]),i("p",null,[a[12]||(a[12]=s("本文由 ")),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>a[10]||(a[10]=[s("LCTT")])),_:1}),a[13]||(a[13]=s(" 原创编译，")),n(e,{href:"https://linux.cn/"},{default:t(()=>a[11]||(a[11]=[s("Linux中国")])),_:1}),a[14]||(a[14]=s(" 荣誉推出"))])])}const x=p(r,[["render",h]]);export{w as __pageData,x as default};
